'use server';

import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { z } from 'zod';

const CreateTaskSchema = z.object({
  title: z.string().min(3),
  projectId: z.string().uuid(),
  priority: z.enum(['LOW', 'MEDIUM', 'HIGH', 'URGENT']),
});

export async function createTaskAction(formData: FormData) {
  const result = CreateTaskSchema.safeParse({
    title: formData.get('title'),
    projectId: formData.get('projectId'),
    priority: formData.get('priority'),
  });

  if (!result.success) {
    return { success: false, errors: result.error.flatten().fieldErrors };
  }

  try {
    await prisma.task.create({
      data: result.data,
    });

    revalidatePath(`/projects/${result.data.projectId}`);
    return { success: true };
  } catch (error) {
    return { success: false, error: 'Failed to create task.' };
  }
}

import { prisma } from '@/lib/prisma';
import { notFound } from 'next/navigation';

interface ProjectPageProps {
  params: Promise<{ id: string }>;
}

export default async function ProjectPage({ params }: ProjectPageProps) {
  const { id } = await params;

  const project = await prisma.project.findUnique({
    where: { id },
    include: {
      tasks: {
        orderBy: [{ isCompleted: 'asc' }, { createdAt: 'desc' }],
      },
    },
  });

  if (!project) notFound();

  return (
    <div className="p-8 max-w-3xl mx-auto">
      <h1 className="text-3xl font-bold mb-2">{project.title}</h1>
      <p className="text-gray-600 mb-6">{project.description}</p>

      <h2 className="text-xl font-semibold mb-4">Tasks ({project.tasks.length})</h2>
      <ul className="space-y-2">
        {project.tasks.map((task) => (
          <li key={task.id} className="p-3 border rounded flex items-center justify-between">
            <span className={task.isCompleted ? 'line-through text-gray-400' : ''}>
              {task.title}
            </span>
            <span className="text-xs font-mono uppercase bg-gray-100 px-2 py-1 rounded">
              {task.priority}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}
